//! Writes the generated files of `packages/soroban-sim-vitest` for the Stellar
//! asset contract (src/generated).
//!
//! Its error table comes from the host's own `ContractError`: the enum is
//! private to the host crate, so its source file is compiled here as a module
//! and the names and codes are the compiler's.
//!
//! Its bindings are stellar-cli's, with the constructs plain Node cannot load
//! rewritten: each rewrite must find its text exactly once, so output from a
//! stellar-cli that generates something else is refused instead of written.
//!
//!   cargo run -p soroban-sim-asset-errors                       write the table
//!   cargo run -p soroban-sim-asset-errors -- --bindings INDEX   write the bindings from stellar-cli's src/index.ts
//!   cargo run -p soroban-sim-asset-errors -- --check            fail if the committed table differs, or the committed bindings lack the rewrites
//!
//! `--check` compares the table with what is written here. Of the bindings it
//! checks only the header and the rewrites: stellar-cli is not run, so the
//! interface itself is not generated again.

#[path = "../../soroban-sim-host/src/builtin_contracts/contract_error.rs"]
mod contract_error;

use contract_error::ContractError;
use num_traits::FromPrimitive;
use soroban_env_common::{xdr::ScErrorType, Error};
use std::{fs, process::ExitCode};

const TABLE: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/../../packages/soroban-sim-vitest/src/generated/stellar-asset-errors.ts"
);

const BINDINGS: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/../../packages/soroban-sim-vitest/src/generated/stellar-asset.ts"
);

const BINDINGS_HEADER: &str = "\
// Generated by `stellar contract bindings typescript --contract-id <the native asset contract>`,
// whose interface is soroban-sdk's for the Stellar asset contract: the src/index.ts
// of the generated package, rewritten by `cargo run -p soroban-sim-asset-errors --
// --bindings <that file>` so that plain Node loads it. CI checks only that this
// file carries that rewrite: the interface itself is not generated again there.

";

/// What Node's type stripping cannot load in stellar-cli's output, and what
/// each becomes: imports of names that are only types, and the constructor's
/// parameter property (a field and an assignment instead).
const REWRITES: [(&str, &str); 3] = [
    (
        "  ClientOptions as ContractClientOptions,\n  MethodOptions,\n  Result,\n",
        "  type ClientOptions as ContractClientOptions,\n  type MethodOptions,\n  type Result,\n",
    ),
    (
        "  constructor(public readonly options: ContractClientOptions) {\n    super(\n",
        "  public readonly options: ContractClientOptions;\n  constructor(options: ContractClientOptions) {\n    super(\n",
    ),
    (
        "      options\n    )\n  }\n  public readonly fromJSON = {",
        "      options\n    )\n    this.options = options\n  }\n  public readonly fromJSON = {",
    ),
];

/// Codes are looked for below this; the host's are all under 16.
const CODES: u32 = 1 << 16;

fn table() -> String {
    let mut rows = String::new();
    for variant in (0..CODES).filter_map(ContractError::from_u32) {
        let name = format!("{variant:?}");
        // `_Reserved1` and the like hold a number the host no longer returns.
        if name.starts_with('_') {
            continue;
        }
        let error = Error::from(variant);
        assert!(error.is_type(ScErrorType::Contract), "{name} is not a contract error");
        rows.push_str(&format!("  ['{name}', {}],\n", error.get_code()));
    }
    format!(
        "// Generated by `cargo run -p soroban-sim-asset-errors` from the host's ContractError\n\
         // (crates/soroban-sim-host/src/builtin_contracts/contract_error.rs). Do not edit:\n\
         // CI fails when this file differs from what that command writes.\n\
         \n\
         /** The host's errors for its built-in contracts, by the code it returns. */\n\
         export const STELLAR_ASSET_ERRORS: readonly [string, number][] = [\n{rows}]\n"
    )
}

/// The bindings file for stellar-cli's `generated` src/index.ts.
fn bindings(generated: &str) -> Result<String, String> {
    let mut written = format!("{BINDINGS_HEADER}{generated}");
    for (from, to) in REWRITES {
        let found = written.matches(from).count();
        if found != 1 {
            return Err(format!(
                "stellar-cli's output has this {found} times, not once; it generates something this does not know how to rewrite:\n{from}"
            ));
        }
        written = written.replacen(from, to, 1);
    }
    Ok(written)
}

/// Whether `committed` carries what `bindings` adds: its header, and every rewrite applied once. The rest of the file is not compared with anything.
fn is_rewritten(committed: &str) -> bool {
    committed.starts_with(BINDINGS_HEADER)
        && REWRITES
            .iter()
            .all(|(from, to)| committed.matches(to).count() == 1 && !committed.contains(from))
}

fn main() -> ExitCode {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let args: Vec<&str> = args.iter().map(String::as_str).collect();
    match args[..] {
        [] => {
            fs::write(TABLE, table()).expect("writing the table");
            ExitCode::SUCCESS
        }
        ["--bindings", generated] => {
            let generated = fs::read_to_string(generated).expect("reading stellar-cli's src/index.ts");
            match bindings(&generated) {
                Ok(written) => {
                    fs::write(BINDINGS, written).expect("writing the bindings");
                    ExitCode::SUCCESS
                }
                Err(why) => {
                    eprintln!("{why}");
                    ExitCode::FAILURE
                }
            }
        }
        ["--check"] => {
            let mut code = ExitCode::SUCCESS;
            if fs::read_to_string(TABLE).ok().as_deref() != Some(table().as_str()) {
                eprintln!("{TABLE} is out of date: run `cargo run -p soroban-sim-asset-errors` and commit the result");
                code = ExitCode::FAILURE;
            }
            if !fs::read_to_string(BINDINGS).is_ok_and(|committed| is_rewritten(&committed)) {
                eprintln!(
                    "{BINDINGS} lacks the header or the plain-Node rewrites that `cargo run -p soroban-sim-asset-errors -- --bindings <stellar-cli's src/index.ts>` writes: \
                     run it on the generated file and commit the result"
                );
                code = ExitCode::FAILURE;
            }
            code
        }
        _ => {
            eprintln!("unknown arguments {args:?}; they are none, `--bindings <stellar-cli's src/index.ts>` or `--check`");
            ExitCode::from(2)
        }
    }
}
